    def route_load(r):
        s = 0
        for c in r:
            s += dem(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        return s + dist(r[-1], depot)

    def insert_cost(r, c, pos):
        a = depot if pos == 0 else r[pos - 1]
        b = depot if pos == len(r) else r[pos]
        return dist(a, c) + dist(c, b) - dist(a, b)

    def angle_key(i):
        p = pt(i)
        return ((p[1] - depot_pt[1]) >= 0, (p[0] - depot_pt[0]), (p[1] - depot_pt[1]), i)

    customers = sorted(customers, key=angle_key)
    unrouted = customers[:]
    routes = []

    if capacity:
        big = []
        for c in unrouted:
            if dem(c) > capacity:
                big.append(c)
        if big:
            for c in big:
                routes.append([c])
            unrouted = [c for c in unrouted if c not in big]

    # Greedy sweep construction with cheapest feasible insertion into open routes
    while unrouted:
        c = unrouted.pop(0)
        best = None
        best_val = None
        for ri, r in enumerate(routes):
            if capacity and route_load(r) + dem(c) > capacity:
                continue
            for pos in range(len(r) + 1):
                v = insert_cost(r, c, pos)
                if best_val is None or v < best_val - 1e-12 or (abs(v - best_val) <= 1e-12 and (ri, pos) < (best[0], best[1])):
                    best = (ri, pos)
                    best_val = v
        if best is None:
            routes.append([c])
        else:
            ri, pos = best
            routes[ri] = routes[ri][:pos] + [c] + routes[ri][pos:]

    # Repair over-capacity routes by splitting
    if capacity:
        repaired = []
        for r in routes:
            cur = []
            cur_load = 0
            for c in r:
                d = dem(c)
                if cur and cur_load + d > capacity:
                    repaired.append(cur)
                    cur = [c]
                    cur_load = d
                else:
                    cur.append(c)
                    cur_load += d
            if cur:
                repaired.append(cur)
        routes = repaired

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r[:]
        best = r[:]
        best_c = route_cost(best)
        improved = True
        while improved:
            improved = False
            n = len(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cc = route_cost(cand)
                    if cc + 1e-12 < best_c:
                        best, best_c = cand, cc
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes if r]

    def total_cost(rs):
        s = 0.0
        for r in rs:
            s += route_cost(r)
        return s

    # Local search: relocate and swap between routes, then 2-opt each affected route
    improved = True
    while improved:
        improved = False
        base = total_cost(routes)

        # Relocate moves
        for a in range(len(routes)):
            if improved:
                break
            ra = routes[a]
            for i, c in enumerate(ra):
                dc = dem(c)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    if capacity and route_load(rb) + dc > capacity:
                        continue
                    for pos in range(len(rb) + 1):
                        nra = ra[:i] + ra[i + 1:]
                        nrb = rb[:pos] + [c] + rb[pos:]
                        cand = routes[:]
                        cand[a] = nra
                        cand[b] = nrb
                        cand = [two_opt(r) for r in cand if r]
                        if total_cost(cand) + 1e-12 < base:
                            routes = cand
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

        if improved:
            continue

        # Swap moves
        for a in range(len(routes)):
            if improved:
                break
            for b in range(a + 1, len(routes)):
                ra = routes[a]
                rb = routes[b]
                la = route_load(ra)
                lb = route_load(rb)
                for i, ca in enumerate(ra):
                    da = dem(ca)
                    for j, cb in enumerate(rb):
                        db = dem(cb)
                        na = la - da + db
                        nb = lb - db + da
                        if capacity and (na > capacity or nb > capacity):
                            continue
                        nra = ra[:]
                        nrb = rb[:]
                        nra[i], nrb[j] = cb, ca
                        cand = routes[:]
                        cand[a] = nra
                        cand[b] = nrb
                        cand = [two_opt(r) for r in cand if r]
                        if total_cost(cand) + 1e-12 < base:
                            routes = cand
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break

    # Final cleanup: remove empties, ensure every customer appears once
    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if c in seen:
                continue
            if capacity and load + dem(c) > capacity:
                if nr:
                    final_routes.append(nr)
                nr = [c]
                load = dem(c)
            else:
                nr.append(c)
                load += dem(c)
            seen.add(c)
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        for r in final_routes:
            if not capacity or route_load(r) + dem(c) <= capacity:
                best_pos = 0
                best_val = None
                for pos in range(len(r) + 1):
                    v = insert_cost(r, c, pos)
                    if best_val is None or v < best_val - 1e-12:
                        best_val = v
                        best_pos = pos
                r[:] = r[:best_pos] + [c] + r[best_pos:]
                placed = True
                break
        if not placed:
            final_routes.append([c])

    final_routes = [two_opt(r) for r in final_routes if r]
    return final_routes
